/**
 * O código do crescimento — porte de `componentes/viz/filotaxia.js`.
 *
 * Aqui o investigador não mexe num ângulo: ele completa a sequência de
 * Fibonacci. O ângulo áureo já está posto, e a flor CRESCE conforme o número
 * digitado — quanto maior o palpite, mais sementes. Quando o número é o certo, a
 * flor desabrocha na hora, antes mesmo de tocar em "verificar": é o próprio
 * desenho dizendo que a resposta fechou.
 *
 * A ligação entre as duas coisas é o assunto do módulo: a espiral que aparece no
 * capítulo é a razão áurea, e a razão áurea é o limite da sequência.
 *
 * Sobre a troca de Three.js por PixiJS, ver `girassol.ts` — mesma solução: as
 * sementes são nuvens de pontos em faixas radiais.
 */

import type { No, Vetor3 } from '../../../viz/cena3d.ts';
import { montar3d } from '../../../viz/cena3d.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** O ângulo áureo em radianos — π(3 − √5). */
const ANGULO_AUREO = Math.PI * (3 - Math.sqrt(5));
const C = 0.34;
const FAIXAS = 8;
const PETALAS = 24;
/** Quantas sementes a flor tem quando fecha. */
const CHEIA = 260;

function hsl(h: number, s: number, l: number): number {
  const f = (n: number): number => {
    const k = (n + h * 12) % 12;
    const a = s * Math.min(l, 1 - l);
    return Math.round(255 * (l - a * Math.max(-1, Math.min(k - 3, 9 - k, 1))));
  };
  return (f(0) << 16) | (f(8) << 8) | f(4);
}

const filotaxia: FabricaViz = (canvas): VizDoPuzzle =>
  montar3d(
    canvas,
    (cena) => {
      const faixas: (No & { pontos: readonly Vetor3[]; cor: number })[] = [];
      for (let i = 0; i < FAIXAS; i++) {
        faixas.push(cena.pontos({ pontos: [], cor: 0xc79a2e, tamanho: 0.17 }));
      }

      // As pétalas nascem vazias: o aro delas só é conhecido quando se sabe
      // quantas sementes a flor tem.
      const petalas: (No & { pontos: readonly Vetor3[] })[] = [];
      for (let i = 0; i < PETALAS; i++) {
        petalas.push(cena.tubo({ pontos: [], cor: 0xffc107, raio: 0.15 }));
      }

      const rotuloSementes = cena.rotulo('sementes', { pos: [0, 1.6, 0], tamanho: 13 });
      const rotuloPetalas = cena.rotulo('pétalas', { pos: [0, 1.2, 0], tamanho: 13 });
      rotuloPetalas.visivel = false;

      cena.animar(() => {
        cena.camera.girar(0.004, 0);
      });

      return {
        aplicar(estado) {
          const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;
          const sequencia = Array.isArray(estado.sequencia) ? (estado.sequencia as number[]) : [];

          const n = Number(valores.n);
          const ultimo = sequencia[sequencia.length - 1];
          const penultimo = sequencia[sequencia.length - 2];
          const esperado =
            ultimo !== undefined && penultimo !== undefined ? ultimo + penultimo : null;

          // Reativo ao que está digitado: a flor floresce antes do "verificar".
          const acertou =
            estado.resolvido === true ||
            (Number.isFinite(n) && esperado !== null && n === esperado);

          const base = Number.isFinite(n) && n > 0 ? Math.min(CHEIA, 60 + n * 8) : 90;
          const total = acertou ? CHEIA : Math.round(base);

          const porFaixa: Vetor3[][] = Array.from({ length: FAIXAS }, () => []);
          for (let i = 0; i < total; i++) {
            const angulo = i * ANGULO_AUREO;
            const r = C * Math.sqrt(i);
            const faixa = Math.min(FAIXAS - 1, Math.floor((i / total) * FAIXAS));
            porFaixa[faixa]?.push([
              Math.cos(angulo) * r,
              0.5 - 0.012 * r * r,
              Math.sin(angulo) * r,
            ]);
          }

          for (let i = 0; i < FAIXAS; i++) {
            const no = faixas[i];
            if (no === undefined) continue;

            const f = i / (FAIXAS - 1);
            no.pontos = porFaixa[i] ?? [];
            no.cor = hsl(0.12 + f * 0.04, 0.8, 0.24 + f * 0.32);
          }

          // O aro das pétalas acompanha o tamanho do capítulo.
          const R = C * Math.sqrt(total) + 0.6;
          for (let i = 0; i < PETALAS; i++) {
            const petala = petalas[i];
            if (petala === undefined) continue;

            petala.visivel = acertou;
            if (!acertou) continue;

            const angulo = (i / PETALAS) * Math.PI * 2;
            petala.pontos = [
              [Math.cos(angulo) * R, 0.1, Math.sin(angulo) * R],
              [Math.cos(angulo) * (R + 1.2), 0.1, Math.sin(angulo) * (R + 1.2)],
            ];
          }

          rotuloSementes.pos = [0, 1.4, 0];
          rotuloPetalas.visivel = acertou;
          rotuloPetalas.pos = [R + 0.6, 0.9, 0];
        },
      };
    },
    { cameraPos: [0, 9, 6], alvo: [0, 0, 0] },
  );

export default filotaxia;
